"""Browser-local JRDB provisional-mail import (code only, no licensed data)."""
HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>競馬ナイン｜JRDBメール取り込み（本人用）</title><link rel=\"stylesheet\" href=\"/jrdb-mail-local.css\"></head><body><main>\n<a href=\"/\">← 本人用ホーム</a>\n<h1>🏇 JRDBメールを取り込む（追加・更新）</h1>\n<p class=\"notice\"><strong>本人用・端末内のみ</strong>。JRDBから届いた「【想確】」メールの本文を貼り付けると、開催日・競馬場・レース別に整理して、この端末内に保存するで。サーバーへのアップロードやGmailへの自動接続はしません。</p>\n<p class=\"warning\">これは<strong>想定確定</strong>で、JRAの最終出馬表・馬番・枠順・取消・当日馬場ではありません。3連単やS/A/B/Cを実戦予想として自動生成しません。転載・一般公開・他人への共有は禁止。</p>\n<section><h2>1. メール本文を貼り付け</h2>\n<label for=\"mailText\">JRDBから届いたメール本文（東京・京都・福島など、1通ずつ、または複数通まとめて）</label>\n<textarea id=\"mailText\" rows=\"8\" maxlength=\"192000\" placeholder=\"■想定確定&#10;&#10;2026年11月7日（土） 5回東京1日目 09:55発走&#10;1Ｒ&#10;...\"></textarea><p class=\"hint\">複数の想定確定メールを1つのUTF-8テキストファイル（.txt）にまとめた場合は、こちらから読み込めます。取り込み前に内容を検査します。</p><label for=\"mailTextFile\">本人用メール本文のテキストファイル（任意）</label><input id=\"mailTextFile\" type=\"file\" accept=\".txt,text/plain\"><p id=\"mailFileStatus\" role=\"status\" class=\"hint\">ファイルの選択だけでは保存しません。検査後に下の「追加・更新」を押してな。</p>\n<button id=\"importMail\" type=\"button\">この端末に追加・更新する</button>\n<p id=\"message\" role=\"status\" class=\"hint\">今日・明日に届く同じ種類のメールは複数通まとめて貼ってOK。更新がある開催は、確認してから入れ替えるで。原文は保存しません。</p></section>\n<section><h2>2. 取り込んだ開催を選択</h2><p class=\"hint\">同じ日付・競馬場なら更新を比較。別の日付や競馬場はそのまま残すで。枠順が付いた確定出馬表は別形式やから、想定メールとして誤って読み込まへん。</p>\n<label for=\"chooseMeeting\">日付・競馬場</label><select id=\"chooseMeeting\"><option value=\"\">取り込んだ開催はまだありません</option></select>\n<p id=\"meetingInfo\" class=\"hint\"></p><div id=\"raceList\"></div><button id=\"deleteMeeting\" type=\"button\" class=\"secondary\">選択した開催だけ削除</button></section>\n<section><button id=\"clearAll\" type=\"button\" class=\"secondary\">この端末の取り込みデータをすべて消す</button>\n<p class=\"hint\">保存先は、このブラウザーの保存領域だけ。Safariと別ブラウザーでは共有されへん。閲覧データを消すと、この予定も消えるで。</p><a href=\"/owner-races\">全開催36Rの準備一覧へ</a> <a href=\"/my-tickets\">3連単の下書きを開く（馬番確定後・手動）</a></section>\n<section id=\"predayPanel\"><h2>明日の「前日情報」から馬番をまとめて取り込む</h2><p class=\"warning\">【前情】のメール本文を東京・京都・福島の3通まとめて貼れます。馬番・馬名・掲載されている脚質（新馬戦などは未確認）と発走予定時刻のみ、このiPhone内に保存。JRA公式の出馬表・取消の独立確認でも、5項目の自動AI評価でもありません。</p><label for=\"predayText\">JRDB「■前日情報」メール本文（複数通OK）</label><textarea id=\"predayText\" rows=\"8\" maxlength=\"192000\" placeholder=\"■前日情報&#10;2026年11月7日（土）　5回東京1日目　09:55発走&#10;1Ｒ&#10;...\"></textarea><p class=\"hint\">メールをコピーしにくい場合は、3開催分をまとめたUTF-8の .txt ファイルも選べます。選択しただけでは保存しません。</p><label for=\"predayTextFile\">前日情報のテキストファイル（任意・本人端末内のみ）</label><input id=\"predayTextFile\" type=\"file\" accept=\".txt,text/plain\"><p id=\"predayFileStatus\" role=\"status\" class=\"hint\">ファイル選択後に全文を検査し、本文欄へ読み込みます。</p><button type=\"button\" id=\"predayImport\">前日情報を検査して取り込む</button><p class=\"hint\" role=\"status\" id=\"predayStatus\">メール本文・IDM・予想印・オッズは保存しません。</p><label for=\"predayMeeting\">日付・競馬場</label><select id=\"predayMeeting\"><option value=\"\">未登録</option></select><p class=\"hint\" id=\"predaySummary\"></p><p id=\"predayDaySummary\" role=\"status\" class=\"hint\">日付ごとの取り込み済みRを確認できます。</p><button type=\"button\" id=\"predayDayToScore\" disabled>選択日の全R評価画面へ進む（次画面で仮登録）</button><p class=\"hint\">移動するだけで採点や下書きを保存しません。評価画面の「全Rを一括仮登録」を押してな。</p><div id=\"predayRaces\"></div><button type=\"button\" id=\"predayDelete\" class=\"secondary\">選択した前日情報だけ削除</button><p class=\"hint\">取り込みは本人用ブラウザー内で完結し、GitHub・Render・Google・公開予想には送信しません。</p></section></main><script src=\"/jrdb-mail-local.js\" defer></script></body></html>"
CSS = "*{box-sizing:border-box}html{color-scheme:dark}body{background:#0a172a;color:#f2f6ff;margin:0;font:15px/1.6 system-ui,sans-serif}main{max-width:780px;margin:auto;padding:18px 14px 50px}h1{font-size:23px;line-height:1.4}h2{font-size:19px;margin-top:0}a{color:#edce82}section{background:#162d49;border:1px solid #42607e;border-radius:15px;padding:15px;margin:16px 0}.notice,.warning{border-radius:11px;padding:12px;background:#243648}.warning{background:#42321e;color:#ffe0aa}label{display:block;font-weight:700;margin:10px 0 7px}textarea,select{display:block;width:100%;font:inherit;padding:12px;background:#0a2036;color:#fff;border:1px solid #7893ad;border-radius:10px}textarea{min-height:160px;resize:vertical}button{width:100%;min-height:48px;margin:10px 0;border:0;border-radius:10px;background:#f1d07b;color:#172b3d;font:inherit;font-weight:800}button.secondary{background:#344b62;color:#e2eaf4}.hint{color:#bcd0e4;font-size:13px}details{background:#0e2137;border:1px solid #425b76;border-radius:10px;margin:9px 0;padding:10px 12px}summary{font-weight:750;cursor:pointer}ul{margin:8px 0 4px;padding-left:23px}li{padding:2px 0}small{display:block;color:#d7bfd2;font-size:12px;margin-top:6px}strong{color:#f0d18e}.warning{border-left:3px solid #e9b968}textarea:focus-visible,select:focus-visible,button:focus-visible{outline:3px solid #f1d07b;outline-offset:2px}\n#predayPanel .preday-open{background:#284662;color:#f2dfae;font-size:14px}#predayPanel .prehorse{font-size:13px;color:#d3e6f9}#predayRaces details{padding:12px;margin:8px 0}"
JS = "'use strict';\n// Client-only, single-person email conversion. No fetch/XHR/analytics,\n// no raw mailbox text persistence and no provider rights transfer.\n(function(){\nconst KEY='keiba-nine-jrdb-personal-mail-v1', MAX_MAIL=64000, MAX_BATCH=12, MAX_TOTAL=192000, MAX_SAVED=48;\nconst TRACKS=['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'];\nconst $=id=>document.getElementById(id);\nconst make=(tag,text)=>{const node=document.createElement(tag);node.textContent=String(text);return node;};\nfunction validDate(year,month,day){\n const d=new Date(Date.UTC(Number(year),Number(month)-1,Number(day)));\n return d.toISOString().slice(0,10)===year+'-'+month.padStart(2,'0')+'-'+day.padStart(2,'0');\n}\nfunction parseJRDBMail(raw){\n if(typeof raw!=='string'||raw.length<100||raw.length>MAX_MAIL||!raw.includes('■想定確定'))\n  throw Error('JRDBの「■想定確定」メール本文を1通ずつ貼ってな。');\n const lines=raw.normalize('NFKC').split(/\\r?\\n/);\n const headers=/^(20\\d{2})年\\s*(\\d{1,2})月\\s*(\\d{1,2})日.*?(札幌|函館|福島|新潟|東京|中山|中京|京都|阪神|小倉)(\\d+)日目\\s+(\\d{1,2}):(\\d{2})発走/;\n let date=null,track=null,previous=null,current=null,inEntries=false;\n const races=[],seen=new Set();\n for(const original of lines){\n  const line=original.trim();\n  if(/^All Rights Reserved|^配\\s*信\\s*:|^このメールに掲載/.test(line))break;\n  const h=headers.exec(line);\n  if(h){\n   if(previous)throw Error('直前の発走時刻に対応するR見出しを読み取れませんでした。');\n   const [unused,y,m,d,t,dayNumber,hh,mm]=h;\n   if(!validDate(y,m,d)||Number(hh)>23||Number(mm)>59)\n    throw Error('開催日時が不正です。');\n   const nextDate=y+'-'+m.padStart(2,'0')+'-'+d.padStart(2,'0');\n   if(date!==null&&(date!==nextDate||track!==t))\n    throw Error('1通の中に異なる日付・競馬場が混じっています。');\n   date=nextDate;track=t;previous={time:hh.padStart(2,'0')+':'+mm, day:dayNumber};\n   current=null;inEntries=false;continue;\n  }\n  // Real JRDB mail may append the race name after \"9R\"/\"10R\"/\"11R\".\n  // Keep only the race number; named titles are never stored.\n  const race=/^(\\d{1,2})R(?:[ \\t]+[^\\r\\n]{1,80})?$/.exec(line);\n  if(race&&previous){\n   const number=Number(race[1]);\n   if(number<1||number>12||seen.has(number)||races.length>=12)\n    throw Error('レース番号の重複、または対象外のRを検出しました。');\n   seen.add(number);\n   current={race:number,postTime:previous.time,expected:null,horses:[]};\n   races.push(current);\n   inEntries=false;previous=null;continue;\n  }\n  if(!current)continue;\n  if(current.expected===null){\n   const x=/(\\d{1,2})頭/.exec(line);\n   if(x){current.expected=Number(x[1]);if(current.expected<1||current.expected>18)\n     throw Error('出走予定頭数が不正です。');}\n  }\n  if(/前評\\s+.*馬名/.test(line)){inEntries=true;continue;}\n  if(!inEntries)continue;\n  // JRDB places up to two one-token evaluation marks before the horse.\n  // These are format markers, NOT our S/A/B horse evaluations.\n  const entrant=/^(?:(?:B|◎|○|△|▲|注|☆|×)\\s+){0,2}([^\\s]+)\\s+(牡|牝|セ)\\s+(\\d{1,2})\\s+/.exec(line);\n  if(entrant){\n   const name=entrant[1];\n   if(name.length>35||current.horses.includes(name))\n    throw Error('馬名が重複または長すぎます。');\n   if(current.horses.length>=18)throw Error('登録頭数の上限を超えています。');\n   current.horses.push(name);\n  }\n }\n if(previous)throw Error('最後のレースの見出しを読み取れませんでした。メールを確認してな。');\n if(!date||!track||!races.length)throw Error('開催日・競馬場・レースを読み取れませんでした。');\n for(const race of races){\n  if(race.expected===null||race.horses.length!==race.expected)\n   throw Error(race.race+'Rの頭数が一致しません。メール本文が途中で切れていないか確認してな。');\n }\n races.sort((a,b)=>a.race-b.race);\n return {date,track,kind:'jrdb-provisional',races};\n}\n\nfunction parseMailBatch(raw){\n if(typeof raw!=='string'||raw.length<100||raw.length>MAX_TOTAL)\n  throw Error('メール本文を貼ってください。まとめて貼れる量は19万文字までです。');\n const normal=raw.replace(/\\r\\n/g,'\\n');\n const starts=[...normal.matchAll(/^■想定確定[ \\t]*$/gm)].map(x=>x.index);\n if(!starts.length||starts.length>MAX_BATCH)\n  throw Error('「■想定確定」メールの本文を1〜12通貼ってください。');\n const meetings=[],keys=new Set();\n for(let i=0;i<starts.length;i++){\n  const item=normal.slice(starts[i],i+1<starts.length?starts[i+1]:normal.length);\n  if(item.length>MAX_MAIL)throw Error((i+1)+'通目が長すぎます。1通64,000文字以内にしてください。');\n  const parsed=parseJRDBMail(item);\n  const key=parsed.date+'|'+parsed.track;\n  if(keys.has(key))throw Error('同じ日付・競馬場のメールが重複しています。1通ずつ確認してな。');\n  keys.add(key);meetings.push(parsed);\n }\n return meetings;\n}\nfunction compareChanges(oldValue,newValue){\n if(!oldValue)return {changed:true,added:newValue.races.length,modified:0};\n const oldRaces=new Map(oldValue.races.map(r=>[r.race,r]));\n if(oldValue.races.some(r=>!newValue.races.some(n=>n.race===r.race)))\n  throw Error(newValue.date+' '+newValue.track+'の新しいメールは以前のレースが欠けています。古い予定は保護したで。');\n let added=0,modified=0;\n for(const race of newValue.races){\n  const old=oldRaces.get(race.race);\n  if(!old){added+=1;continue;}\n  if(old.postTime!==race.postTime||old.expected!==race.expected||\n     JSON.stringify(old.horses)!==JSON.stringify(race.horses))modified+=1;\n }\n return {changed:added+modified>0,added,modified};\n}\nfunction validSaved(x){\n return x&&x.kind==='jrdb-provisional'&&typeof x.date==='string'&&\n /^\\d{4}-\\d{2}-\\d{2}$/.test(x.date)&&TRACKS.includes(x.track)&&\n Array.isArray(x.races)&&x.races.length>=1&&x.races.length<=12&&\n x.races.every(r=>r&&Number.isInteger(r.race)&&r.race>=1&&r.race<=12&&\n /^\\d{2}:\\d{2}$/.test(r.postTime)&&Number.isInteger(r.expected)&&\n r.expected>=1&&r.expected<=18&&Array.isArray(r.horses)&&\n r.horses.length===r.expected&&r.horses.every(n=>typeof n==='string'&&n.length>=1&&n.length<=35))&&\n new Set(x.races.map(r=>r.race)).size===x.races.length;\n}\nlet meetings=[];\ntry{\n const data=JSON.parse(localStorage.getItem(KEY)||'[]');\n if(Array.isArray(data))meetings=data.slice(-MAX_SAVED).filter(validSaved);\n}catch(_){meetings=[];}\nfunction show(){\n const chosen=$('chooseMeeting').value;\n const select=$('chooseMeeting');select.replaceChildren();\n select.append(make('option',meetings.length?'開催を選択':'取り込み済みの開催はありません'));\n select.children[0].value='';\n const sorted=meetings.slice().sort((a,b)=>b.date.localeCompare(a.date)||TRACKS.indexOf(a.track)-TRACKS.indexOf(b.track));\n for(const item of sorted){\n  const opt=make('option',item.date+' '+item.track+'｜'+item.races.length+'R');\n  opt.value=item.date+'|'+item.track;select.append(opt);\n }\n const key=sorted.some(m=>m.date+'|'+m.track===chosen)?chosen:\n  (sorted[0]?sorted[0].date+'|'+sorted[0].track:'');\n select.value=key;\n const chosenMeeting=sorted.find(m=>m.date+'|'+m.track===key);\n const list=$('raceList');list.replaceChildren();\n if(!chosenMeeting){$('meetingInfo').textContent='まだ開催データがありません。';return;}\n const sum=chosenMeeting.races.reduce((n,r)=>n+r.expected,0);\n $('meetingInfo').textContent=chosenMeeting.date+'・'+chosenMeeting.track+\n  '／'+chosenMeeting.races.length+'レース・想定登録'+sum+'頭。馬番・枠・取消は未確定。';\n for(const race of chosenMeeting.races){\n  const details=document.createElement('details');\n  details.append(make('summary',race.race+'R｜'+race.postTime+'（想定）｜'+race.expected+'頭'));\n  const small=make('small','※想定資料。馬番・枠順はありません。JRA出馬表で最終確認が必要。');\n  details.append(small);\n  const names=document.createElement('ul');\n  for(const name of race.horses)names.append(make('li',name));\n  details.append(names);list.append(details);\n }\n}\nlet fileReadToken=0;\n$('mailTextFile').onchange=async()=>{\n const file=$('mailTextFile').files&&$('mailTextFile').files[0];\n const token=++fileReadToken;\n if(!file){$('mailFileStatus').textContent='ファイルが選択されていません。';return;}\n try{\n  if(typeof file.name==='string'&&!/\\.txt$/i.test(file.name))\n   throw Error('UTF-8の .txt ファイルだけを選択してな。');\n  if(!Number.isSafeInteger(file.size)||file.size<100||file.size>MAX_TOTAL)\n   throw Error('ファイルは100バイト〜192KB以内のテキストにしてな。');\n  const contents=await file.text();\n  if(token!==fileReadToken||!$('mailTextFile').files||\n     $('mailTextFile').files[0]!==file)return;\n  if(contents.length>MAX_TOTAL)throw Error('読み込んだ本文が192,000文字を超えています。');\n  const meetingsToReview=parseMailBatch(contents);\n  if($('mailText').value.trim()&&\n     !confirm('現在貼付中のメール本文を、ファイルから読み込んだ'+\n      meetingsToReview.length+'開催分で置き換えますか？'))return;\n  $('mailText').value=contents;\n  $('mailFileStatus').textContent=meetingsToReview.length+\n   '開催分を検査できました。まだ未保存です。下の「この端末に追加・更新する」を押してな。';\n }catch(e){\n  $('mailFileStatus').textContent='ファイルを読み込めません：'+\n   (e instanceof Error?e.message:'内容を確認してな。');\n }\n};\n$('importMail').onclick=()=>{\n try{\n  // Validate the entire pasted batch BEFORE changing any saved meeting.\n  const incoming=parseMailBatch($('mailText').value);\n  const updates=[],replacement=meetings.slice();\n  let added=0,modified=0,changedExisting=false;\n  for(const item of incoming){\n   const index=replacement.findIndex(m=>m.date===item.date&&m.track===item.track);\n   const before=index<0?null:replacement[index];\n   const change=compareChanges(before,item);\n   if(!change.changed)continue;\n   if(index>=0)changedExisting=true;\n   if(index<0)replacement.push(item);\n   else replacement[index]=item;\n   added+=change.added;modified+=change.modified;\n   updates.push(item.date+' '+item.track+'（新規'+change.added+'R・変更'+change.modified+'R）');\n  }\n  if(replacement.length>MAX_SAVED)\n   throw Error('最大48開催まで保存できます。不要な開催を削除してから再試行してな。');\n  if(changedExisting&&\n     !confirm('取り込み予定 '+incoming.length+'通\\n'+updates.join('\\n')+\n      '\\nほかの日付・競馬場、買い目・購入記録は変更しません。更新しますか？'))\n   return;\n  if(updates.length){\n   // One transaction: on quota failure, leave the previous localStorage intact.\n   localStorage.setItem(KEY,JSON.stringify(replacement));\n   meetings=replacement;\n  }\n  $('mailText').value='';\n  show();\n  const last=incoming[incoming.length-1];\n  $('chooseMeeting').value=last.date+'|'+last.track;\n  $('chooseMeeting').onchange();\n  $('message').textContent=incoming.length+'通を確認。'+updates.length+'開催を追加・更新、'+\n   (incoming.length-updates.length)+'開催は変更なし。新規'+added+'R、変更'+modified+\n   'R。原文は保存せず、馬番・枠順は未確定のままやで。';\n }catch(e){$('message').textContent='取り込めません：'+(e&&e.message||'メール形式を確認してな。');}\n};\n$('chooseMeeting').onchange=()=>{\n const key=$('chooseMeeting').value;\n const selected=meetings.find(m=>m.date+'|'+m.track===key);\n const list=$('raceList');list.replaceChildren();\n if(!selected){$('meetingInfo').textContent='開催を選んでな。';return;}\n $('meetingInfo').textContent=selected.date+' '+selected.track+'｜'+selected.races.length+'R（想定・馬番未確定）';\n for(const race of selected.races){\n  const details=document.createElement('details');\n  details.append(make('summary',race.race+'R｜'+race.postTime+'（想定）｜'+race.expected+'頭'));\n  details.append(make('small','馬番・枠順・取消・当日馬場は未確定。JRA公式で照合してな。'));\n  const names=document.createElement('ul');\n  for(const name of race.horses)names.append(make('li',name));\n  details.append(names);list.append(details);\n }\n};\n$('deleteMeeting').onclick=()=>{\n const key=$('chooseMeeting').value;\n if(!key)return;\n const target=meetings.find(m=>m.date+'|'+m.track===key);\n if(!target)return;\n if(!confirm(target.date+' '+target.track+'の取り込み済み予定だけを消しますか？\\n他の開催や購入記録は残ります。'))return;\n const next=meetings.filter(m=>m!==target);\n try{localStorage.setItem(KEY,JSON.stringify(next));\n  meetings=next;show();\n  $('message').textContent=target.date+' '+target.track+'の想定予定だけを削除したで。';\n }catch(_){$('message').textContent='保存できませんでした。元の予定はそのままです。';}\n};\n$('clearAll').onclick=()=>{\n if(!meetings.length)return;\n if(!confirm('この端末に保存したJRDB想定メールの予定データを全部消しますか？ 3連単の下書き・実購入記録は消しません。'))return;\n try{localStorage.removeItem(KEY);meetings=[];show();\n $('message').textContent='想定メールの取り込みデータだけを削除したで。';}\n catch(_){$('message').textContent='削除できませんでした。ブラウザーの設定を確認してな。';}\n};\nshow();\n\n// JRDB 前日情報: a PRIVATE local race-number reference only (not JRA\n// verified, not a forecast). No IDM, provider ratings, marks, odds or raw mail.\nconst PREDAY='keiba-nine-jrdb-preday-runners-v1';\nfunction parsePredayOne(raw){\n if(typeof raw!=='string'||raw.length<100||raw.length>MAX_MAIL||!raw.includes('■前日情報'))\n  throw Error('「■前日情報」メールの本文を貼ってな。');\n const lines=raw.normalize('NFKC').replace(/\\r/g,'').split('\\n');\n const head=/^(20\\d{2})年\\s*(\\d{1,2})月\\s*(\\d{1,2})日.*?(札幌|函館|福島|新潟|東京|中山|中京|京都|阪神|小倉)\\s*\\d+日目\\s+(\\d{1,2}):(\\d{2})発走/;\n let date='',track='',waiting=null,current=null,inEntries=false;\n const races=[],used=new Set();\n for(const original of lines){\n  const line=original.trim();\n  if(/^このメールに掲載|^All Rights Reserved|^配\\s*信\\s*:/.test(line))break;\n  const m=head.exec(line);\n  if(m){\n   if(waiting)throw Error('前のRの番号が欠けています。');\n   const [,y,mo,d,t,hh,mm]=m;\n   if(!validDate(y,mo,d)||+hh>23||+mm>59)throw Error('開催日時が不正です。');\n   const dt=y+'-'+mo.padStart(2,'0')+'-'+d.padStart(2,'0');\n   if(date&&(date!==dt||track!==t))throw Error('1通に複数の開催が混じっています。');\n   date=dt;track=t;waiting={postTime:hh.padStart(2,'0')+':'+mm};\n   current=null;inEntries=false;continue;\n  }\n  const r=/^([1-9]|1[0-2])\\s*R(?:\\s+.{1,80})?$/.exec(line);\n  if(r&&waiting){\n   const n=+r[1];if(used.has(n))throw Error('R番号が重複しています。');\n   used.add(n);current={race:n,postTime:waiting.postTime,expected:null,runners:[]};\n   races.push(current);waiting=null;inEntries=false;continue;\n  }\n  if(!current)continue;\n  if(current.expected===null){\n   const c=/(\\d{1,2})頭(?:立)?/.exec(line);\n   if(c){current.expected=+c[1];\n    if(current.expected<3||current.expected>18)throw Error(current.race+'Rの頭数が不正です。');}\n  }\n  if(/騎情ID前/.test(line)&&/馬名/.test(line)){inEntries=true;continue;}\n  if(!inEntries)continue;\n  const h=/^[^0-9\\n]{0,13}?\\s*([1-9]|1[0-8])\\s+([^\\s]+)\\s+(牡|牝|セ)\\s*(\\d{1,2})\\s+(.+)$/.exec(line);\n  if(!h)continue;\n  const n=+h[1],age=+h[4],style=/(?:^|\\s)(逃|先|差|追)(?=\\s|$)/.exec(h[5])?.[1]||'未確認';\n  if(age<2||age>15)throw Error(current.race+'Rの馬番・年齢の形式が不正です。');\n  let name=h[2];if(/^B[ァ-ヿぁ-ゟ一-龯]/.test(name))name=name.slice(1);\n  if(!name||name.length>35||/[<>]/.test(name)||\n     current.runners.some(x=>x.number===n||x.name===name))\n   throw Error(current.race+'Rの馬番・馬名に重複があります。');\n  current.runners.push({number:n,name,style});\n }\n if(waiting)throw Error('最後のR番号が欠けています。');\n if(!date||!track||!races.length||races.length>12)throw Error('開催とRを確認できません。');\n for(const r of races){\n  if(!r.expected||r.runners.length!==r.expected)\n   throw Error(track+r.race+'Rの'+r.expected+'頭中'+r.runners.length+'頭しか読めません。全文を確認してな。');\n  r.runners.sort((a,b)=>a.number-b.number);\n }\n races.sort((a,b)=>a.race-b.race);\n return {kind:'jrdb-preday-provisional',date,track,races};\n}\nfunction predayBatch(raw){\n if(typeof raw!=='string'||raw.length<100||raw.length>MAX_TOTAL)throw Error('前日情報を1〜12通貼ってな。');\n const content=raw.replace(/\\r\\n/g,'\\n');\n const starts=[...content.matchAll(/^■前日情報[ \\t]*$/gm)].map(x=>x.index);\n if(starts.length<1||starts.length>MAX_BATCH)throw Error('前日情報の見出しがありません。');\n const meetings=[],ids=new Set();\n for(let i=0;i<starts.length;i++){\n  const item=parsePredayOne(content.slice(starts[i],i+1<starts.length?starts[i+1]:content.length));\n  const id=item.date+'|'+item.track;\n  if(ids.has(id))throw Error('同じ日付・競馬場が重複しています。');\n  ids.add(id);meetings.push(item);\n }\n return meetings;\n}\nfunction validPreday(v){\n if(!v||v.kind!=='jrdb-preday-provisional'||!/^\\d{4}-\\d{2}-\\d{2}$/.test(v.date)||\n    !TRACKS.includes(v.track)||!Array.isArray(v.races)||\n    v.races.length<1||v.races.length>12)return false;\n const seen=new Set();\n return v.races.every(r=>{\n  if(!r||!Number.isInteger(r.race)||r.race<1||r.race>12||seen.has(r.race)||\n     typeof r.postTime!=='string'||!/^\\d\\d:\\d\\d$/.test(r.postTime)||\n     !Number.isInteger(r.expected)||r.expected<3||r.expected>18||\n     !Array.isArray(r.runners)||r.runners.length!==r.expected)return false;\n  seen.add(r.race);const ids=new Set(),names=new Set();\n  return r.runners.every(h=>{\n   if(!h||!Number.isInteger(h.number)||h.number<1||h.number>18||\n      typeof h.name!=='string'||h.name.length<1||h.name.length>35||\n      !['逃','先','差','追','未確認'].includes(h.style)||ids.has(h.number)||names.has(h.name))return false;\n   ids.add(h.number);names.add(h.name);return true;\n  });\n });\n}\nfunction predayRead(){\n try{\n  const rows=JSON.parse(localStorage.getItem(PREDAY)||'[]');\n  if(!Array.isArray(rows)||rows.length>MAX_SAVED||!rows.every(validPreday)||\n     new Set(rows.map(x=>x.date+'|'+x.track)).size!==rows.length)throw Error('broken');\n  return rows;\n }catch(_){return null;}\n}\nfunction predayShow(){\n const all=predayRead(),select=$('predayMeeting'),requested=select.value;\n $('predayDayToScore').disabled=true;\n select.replaceChildren();const start=make('option',all?.length?'開催を選ぶ':'未取り込み');start.value='';select.append(start);\n const host=$('predayRaces');host.replaceChildren();\n if(!all){$('predaySummary').textContent='保存済みの前日情報が破損しています。上書きを停止します。';$('predayDaySummary').textContent='復元前にデータを確認してな。';return;}\n const order=all.slice().sort((a,b)=>b.date.localeCompare(a.date)||TRACKS.indexOf(a.track)-TRACKS.indexOf(b.track));\n for(const m of order){\n  const opt=make('option',m.date+' '+m.track+'｜'+m.races.length+'R（前日資料）');\n  opt.value=m.date+'|'+m.track;select.append(opt);\n }\n select.value=order.some(x=>x.date+'|'+x.track===requested)?requested:\n  order.length?order[0].date+'|'+order[0].track:'';\n const chosen=order.find(x=>x.date+'|'+x.track===select.value);\n if(!chosen){$('predaySummary').textContent='まだ前日情報はありません。';$('predayDaySummary').textContent='取り込んだ開催はありません。';return;}\n const matched=order.filter(x=>x.date===chosen.date),raceCount=matched.reduce((n,x)=>n+x.races.length,0);\n $('predayDaySummary').textContent='この日の登録済み：'+matched.length+'開催／'+raceCount+'R。'+\n  (raceCount===36?'全36Rの入力準備が可能です。':'36Rの全登録は未確認です。')+' JRA公式未照合。';\n $('predayDayToScore').disabled=false;\n $('predaySummary').textContent=chosen.date+' '+chosen.track+' '+chosen.races.length+\n  '/12R・'+chosen.races.reduce((n,r)=>n+r.expected,0)+'頭（JRA公式未照合）';\n for(const race of chosen.races){\n  const block=document.createElement('details');\n  block.append(make('summary',race.race+'R｜'+race.postTime+'発走予定｜'+race.expected+'頭'));\n  const list=document.createElement('ul');\n  for(const runner of race.runners)list.append(make('li',runner.number+'番 '+runner.name+'（'+runner.style+'）'));\n  block.append(list);\n  const btn=make('button',race.race+'Rを5項目評価で開く');\n  btn.type='button';btn.className='preday-open';\n  btn.onclick=()=>{\n   const q=new URLSearchParams({select:'v1',date:chosen.date,track:chosen.track,race:String(race.race)});\n   window.location.assign('/my-scorecard#'+q.toString());\n  };\n  block.append(btn);host.append(block);\n }\n}\nlet predayFileToken=0;\n$('predayTextFile').onchange=async()=>{\n const file=$('predayTextFile').files&&$('predayTextFile').files[0];\n const token=++predayFileToken,beforeText=$('predayText').value;\n if(!file){$('predayFileStatus').textContent='ファイルが選択されていません。';return;}\n try{\n  if(typeof file.name!=='string'||! /\\.txt$/i.test(file.name))\n   throw Error('UTF-8の .txt ファイルだけ選んでな。');\n  if(!Number.isSafeInteger(file.size)||file.size<100||file.size>MAX_TOTAL)\n   throw Error('100バイト〜192KB以内のテキストを選んでな。');\n  const contents=await file.text();\n  if(token!==predayFileToken||!$('predayTextFile').files||\n     $('predayTextFile').files[0]!==file)return;\n  if($('predayText').value!==beforeText){$('predayFileStatus').textContent='本文が編集中に変わりました。ファイルを選び直してな。';return;}\n  if(contents.length>MAX_TOTAL)throw Error('本文が192,000文字を超えています。');\n  const validated=predayBatch(contents);\n  if(beforeText.trim()&&!confirm('入力中の本文を、ファイルから検査した'+validated.length+'開催分で置き換えますか？'))return;\n  $('predayText').value=contents;\n  $('predayFileStatus').textContent=validated.length+'開催／'+validated.reduce((n,m)=>n+m.races.length,0)+\n   'Rを検査しました。まだ未保存です。「前日情報を検査して取り込む」を押してな。';\n }catch(e){\n  if(token===predayFileToken)$('predayFileStatus').textContent='ファイルを読み込めません：'+\n   (e instanceof Error?e.message:'形式を確認してな。');\n }\n};\n$('predayDayToScore').onclick=()=>{\n const all=predayRead(),key=$('predayMeeting').value;\n const m=all?.find(x=>x.date+'|'+x.track===key);\n if(!m){$('predayDaySummary').textContent='評価へ進めません。前日情報を選択してな。';return;}\n const race=m.races.some(x=>x.race===1)?1:m.races[0].race;\n const q=new URLSearchParams({select:'v1',date:m.date,track:m.track,race:String(race)});\n window.location.assign('/my-scorecard#'+q.toString());\n};\n$('predayImport').onclick=()=>{\n try{\n  const batch=predayBatch($('predayText').value),all=predayRead();\n  if(!all)throw Error('端末の保存済み前日情報が破損しています。');\n  const next=all.slice(),updates=[];\n  for(const item of batch){\n   const i=next.findIndex(x=>x.date===item.date&&x.track===item.track),old=i<0?null:next[i];\n   if(old&&old.races.some(r=>!item.races.some(x=>x.race===r.race)))\n    throw Error('新しい前日情報に旧Rが欠けています。保存済み資料を保護します。');\n   if(old&&JSON.stringify(old)===JSON.stringify(item))continue;\n   if(i<0)next.push(item);else next[i]=item;\n   updates.push(item.date+' '+item.track+(i<0?'新規':'更新'));\n  }\n  if(next.length>MAX_SAVED)throw Error('最大48開催までです。');\n  if(updates.some(x=>x.endsWith('更新'))&&\n     !confirm(updates.join('／')+'の前日資料を更新しますか？\\n5項目採点済みメモは自動変更しません。'))return;\n  if(updates.length)localStorage.setItem(PREDAY,JSON.stringify(next));\n  $('predayText').value='';$('predayTextFile').value='';predayFileToken++;predayShow();\n  $('predayMeeting').value=batch[batch.length-1].date+'|'+batch[batch.length-1].track;predayShow();\n  $('predayStatus').textContent=batch.length+'通の前日情報から'+batch.reduce((n,x)=>n+x.races.length,0)+\n   'Rを検査、'+updates.length+'開催を保存・更新。馬番・脚質は前日資料であり公式未照合です。';\n }catch(e){$('predayStatus').textContent='取り込めません：'+\n  (e instanceof Error?e.message:'本文を確認してな。');}\n};\n$('predayMeeting').onchange=predayShow;\n$('predayDelete').onclick=()=>{\n const all=predayRead(),key=$('predayMeeting').value;\n if(!all||!key)return;\n const item=all.find(x=>x.date+'|'+x.track===key);\n if(!item||!confirm('前日情報 '+key+'だけを削除しますか？\\n購入記録・採点は残ります。'))return;\n try{localStorage.setItem(PREDAY,JSON.stringify(all.filter(x=>x!==item)));\n  predayShow();$('predayStatus').textContent='選択した前日資料だけを削除しました。';\n }catch(_){$('predayStatus').textContent='削除に失敗しました。';}\n};\npredayShow();\n\n})();"
